-- A 2-stage pipelined 8×8 multiplier. Stage 1 forms two partial products
-- (a × low nibble of b, a × high nibble); stage 2 adds them. One result
-- per cycle, two cycles of latency.
xblue module mkMul2;
  input Bool reset;
  input Bool in_valid;
  input Bit#(8) in_a;
  input Bit#(8) in_b;

  Reg#(Bool)     v1 <- mkReg(0);
  Reg#(Bit#(16)) lo <- mkReg(0);
  Reg#(Bit#(16)) hi <- mkReg(0);
  Reg#(Bool)     v2 <- mkReg(0);
  Reg#(Bit#(16)) p  <- mkReg(0);

  Bit#(16) a16 = zeroExtend(in_a);
  Bit#(16) bl  = zeroExtend(in_b[3:0]);
  Bit#(16) bh  = zeroExtend(in_b[7:4]);

  method Bool     out_valid = v2;
  method Bit#(16) out_p     = p;

  -- the later stage runs first in the cycle, so it reads stage 1's old
  -- contents before stage 1 overwrites them: a real pipeline register
  rule mul;
    v2 <= in_valid;
    p <= a16 * zeroExtend(in_b);
  endrule

  rule clear (reset);
    v1 <= False;
    v2 <= False;
  endrule

  schedule mul ≫ clear;
endmodule
